css:
.card {
  --color-primary: #11140e;
  --color-border: #8a8b90;

  width: 200px;
  height: 200px;
  position: relative;
  color: white;
  box-shadow: rgba(100, 100, 111, 0.2) 0px 7px 29px 0px;
}

.card:hover {
  transition: 0.8s ease-in-out;
}

.top-card {
  width: 200px;
  height: 200px;
  background-color: var(--color-primary);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  position: absolute;
  z-index: 1;
  display: flex;
  justify-content: center;
  align-items: center;
}

.top-card svg {
  width: 50px;
  height: 50px;
  fill: var(--color-border);
}

.bottom-card {
  width: 200px;
  height: 120px;
  background-color: var(--color-primary);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  position: relative;
  transition:
    margin-left 0.4s ease-in-out,
    margin-top 0.3s ease-in-out 0.4s;
  padding: 4%;
  padding-top: 45px;
}

.card:hover .bottom-card {
  margin-top: 160px;
  margin-left: 20px;
  transition:
    margin-top 0.4s ease-in-out,
    margin-left 0.3s ease-in-out 0.4s;
}

.bottom-card-title {
  font-size: 20px;
  font-weight: bold;
}

.bottom-card-content {
  font-size: 14px;
}
